/**
 * Point the poster at an Instagram access token.
 *
 * Run this after pasting a new token into IG_ACCESS_TOKEN in .env — whenever the
 * account changes, or if a token ever expires and has to be regenerated by hand.
 *
 *   node automation/n8n/set-instagram-token.mjs
 *
 * It validates the token against Meta, shows which account it belongs to, then
 * rewrites instagram-token.json and IG_USER_ID to match.
 *
 * Why this exists: the workflows read the token from instagram-token.json, not
 * from .env. .env is only the seed. Editing .env alone leaves the old token in
 * place and the poster keeps publishing to the previous account with no error.
 * This script keeps the two in step.
 *
 * The token is never printed.
 */
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const DIR = path.dirname(fileURLToPath(import.meta.url));
const ENV = path.join(DIR, '.env');
const STORE = path.join(DIR, 'instagram-token.json');

const readEnv = () =>
  Object.fromEntries(
    fs.readFileSync(ENV, 'utf8')
      .split(/\r?\n/)
      .filter((l) => /^[A-Z0-9_]+=/.test(l))
      .map((l) => { const i = l.indexOf('='); return [l.slice(0, i), l.slice(i + 1).trim()]; })
  );

let env;
try {
  env = readEnv();
} catch {
  console.error(`Cannot read ${ENV}`);
  process.exit(1);
}

const token = env.IG_ACCESS_TOKEN;
const base = (env.IG_GRAPH_BASE || 'https://graph.instagram.com/v23.0').replace(/\/+$/, '');

if (!token) {
  console.error('IG_ACCESS_TOKEN is empty in .env. Paste the token there first.');
  process.exit(1);
}
if (/\s/.test(token)) {
  console.error('IG_ACCESS_TOKEN contains a space or line break — it must be one unbroken line.');
  process.exit(1);
}

const previous = fs.existsSync(STORE)
  ? JSON.parse(fs.readFileSync(STORE, 'utf8')).boundTo
  : null;

const auth = { Authorization: `Bearer ${token}` };
const me = await (await fetch(`${base}/me?fields=id,username,account_type,media_count`, { headers: auth })).json();

if (me.error) {
  console.error('\nToken rejected by Instagram:');
  console.error('  ' + (me.error.message || JSON.stringify(me.error)));
  console.error('\nNothing was changed. Generate a fresh token and try again.');
  process.exit(1);
}

if (me.account_type !== 'BUSINESS' && me.account_type !== 'MEDIA_CREATOR') {
  console.error(`\nAccount @${me.username} is ${me.account_type}, which cannot publish via the API.`);
  console.error('Switch it to a Business or Creator account first.');
  process.exit(1);
}

// Ask Meta for the real expiry. A token minted in the last 24h can't be
// refreshed yet, so fall back to the documented 60 days.
let expiresAt = null;
try {
  const j = await (await fetch(
    `${base.replace(/\/v[\d.]+$/, '')}/refresh_access_token?grant_type=ig_refresh_token&access_token=${encodeURIComponent(token)}`
  )).json();
  if (j.expires_in) expiresAt = new Date(Date.now() + Number(j.expires_in) * 1000).toISOString();
} catch { /* fall through to the estimate */ }

const estimated = !expiresAt;
if (!expiresAt) expiresAt = new Date(Date.now() + 60 * 86400 * 1000).toISOString();

fs.writeFileSync(STORE, JSON.stringify({
  accessToken: token,
  seededAt: new Date().toISOString(),
  expiresAt,
  boundTo: me.username,
}, null, 2) + '\n', 'utf8');

fs.writeFileSync(ENV, fs.readFileSync(ENV, 'utf8').replace(/^IG_USER_ID=.*$/m, `IG_USER_ID=${me.id}`), 'utf8');

console.log('Token accepted.\n');
if (previous && previous !== me.username) console.log(`  switched from : @${previous}`);
console.log(`  now posting to: @${me.username}`);
console.log(`  account id    : ${me.id}`);
console.log(`  account type  : ${me.account_type}`);
console.log(`  existing posts: ${me.media_count}`);
console.log(`  expires       : ${expiresAt.slice(0, 10)}${estimated ? ' (estimated — the Monday refresh will correct it)' : ' (confirmed by Meta)'}`);
console.log('\nUpdated instagram-token.json and IG_USER_ID. Restart n8n to pick up the new id.');
